import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.B65tnXzx.js";const u=JSON.parse('{"title":"术语表","description":"","frontmatter":{"title":"术语表","titleEn":"Glossary","category":"guide","outline":"deep"},"headers":[],"relativePath":"zh/glossary.md","filePath":"zh/glossary.md"}'),o={name:"zh/glossary.md"};function l(n,t,h,i,c,s){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="📚-术语表" tabindex="-1">📚 术语表 <a class="header-anchor" href="#📚-术语表" aria-label="Permalink to &quot;📚 术语表&quot;">​</a></h1><blockquote><p>本文档使用的英中双语术语对照表。所有页面的术语保持统一。</p></blockquote><h2 id="核心术语" tabindex="-1">核心术语 <a class="header-anchor" href="#核心术语" aria-label="Permalink to &quot;核心术语&quot;">​</a></h2><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>Notes</th></tr></thead><tbody><tr><td>Effect</td><td>效果</td><td>被执行的动作，如造成伤害、生成粒子</td></tr><tr><td>Trigger</td><td>触发器</td><td>导致效果运行的事件/动作</td></tr><tr><td>Condition</td><td>条件</td><td>效果激活前必须满足的要求</td></tr><tr><td>Mutator</td><td>变异器</td><td>在效果运行前修改传给效果的数据</td></tr><tr><td>Filter</td><td>过滤器</td><td>通过限制目标来收窄触发器激活时机</td></tr><tr><td>Chain</td><td>效果链</td><td>在同一个触发器下一起执行的一组效果</td></tr><tr><td>Cooldown</td><td>冷却时间</td><td>两次效果激活之间的时间</td></tr><tr><td>Chance</td><td>触发概率</td><td>效果激活的百分比概率</td></tr><tr><td>Target</td><td>目标</td><td>效果作用的实体</td></tr><tr><td>Entity</td><td>实体</td><td>游戏世界中的生物、玩家或物体</td></tr><tr><td>Victim</td><td>受害者/目标</td><td>受动作影响的实体</td></tr><tr><td>Dispatcher</td><td>派发者</td><td>触发效果的实体</td></tr><tr><td>Holder</td><td>持有者</td><td>持有效果的配置（附魔、护符、重铸等）</td></tr><tr><td>Placeholder</td><td>占位符</td><td>类似 <code>%level%</code> 的令牌，解析为某个值</td></tr><tr><td>Multiplier</td><td>倍率/乘数</td><td>用于乘以另一个值的数值</td></tr><tr><td>Amplifier</td><td>增幅器</td><td>药水效果的增幅等级</td></tr><tr><td>Duration</td><td>持续时间</td><td>效果的持续时长</td></tr><tr><td>Stacking</td><td>叠加</td><td>多个同类效果组合</td></tr><tr><td>Configuration</td><td>配置</td><td>定义行为的 YAML 设置</td></tr><tr><td>YAML</td><td>YAML</td><td>人类可读的数据序列化格式（不翻译）</td></tr><tr><td>Permanent Effect</td><td>永久型效果</td><td>满足条件时始终生效的效果</td></tr><tr><td>Triggered Effect</td><td>触发型效果</td><td>需要触发器激活的效果</td></tr></tbody></table><h2 id="参数与选项术语" tabindex="-1">参数与选项术语 <a class="header-anchor" href="#参数与选项术语" aria-label="Permalink to &quot;参数与选项术语&quot;">​</a></h2><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>Notes</th></tr></thead><tbody><tr><td>args</td><td>参数</td><td>效果/条件/变异器的参数</td></tr><tr><td>chance</td><td>触发概率</td><td>百分比激活概率</td></tr><tr><td>cost</td><td>花费</td><td>激活所需金钱（Vault）</td></tr><tr><td>every</td><td>每隔</td><td>每 x 次激活一次</td></tr><tr><td>require</td><td>要求</td><td>要求表达式为真</td></tr><tr><td>cooldown</td><td>冷却</td><td>以秒计的冷却时间</td></tr><tr><td>cooldown_group</td><td>冷却组</td><td>共享冷却组</td></tr><tr><td>mana_cost</td><td>法力消耗</td><td>法力/魔法消耗（AuraSkills/EcoSkills）</td></tr><tr><td>delay</td><td>延迟</td><td>执行前等待的刻数</td></tr><tr><td>repeat</td><td>重复</td><td>重复激活</td></tr><tr><td>price</td><td>价格</td><td>激活所需价格</td></tr><tr><td>run-order</td><td>运行顺序</td><td>执行顺序：start/early/normal/late/end</td></tr><tr><td>load-weight</td><td>加载权重</td><td>配置加载顺序权重</td></tr><tr><td>inverse</td><td>反向</td><td>取反条件</td></tr><tr><td>not-met-lines</td><td>未满足提示行</td><td>条件未满足时显示的物品说明行</td></tr><tr><td>not-met-effects</td><td>未满足效果</td><td>条件未满足时运行的效果</td></tr></tbody></table><h2 id="ecoenchants-术语" tabindex="-1">EcoEnchants 术语 <a class="header-anchor" href="#ecoenchants-术语" aria-label="Permalink to &quot;EcoEnchants 术语&quot;">​</a></h2><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>Notes</th></tr></thead><tbody><tr><td>Enchantment</td><td>附魔</td><td>自定义附魔</td></tr><tr><td>max-level</td><td>最高等级</td><td>附魔的最高等级</td></tr><tr><td><code>%level%</code></td><td>等级占位符</td><td>返回附魔等级</td></tr><tr><td>Rarity</td><td>稀有度</td><td>控制附魔的获取方式</td></tr><tr><td>Target</td><td>目标物品</td><td>附魔可应用的物品</td></tr><tr><td>Conflict</td><td>冲突</td><td>不能共存的附魔</td></tr><tr><td>Spell Enchantment</td><td>法术附魔</td><td>按 alt 点击激活、带冷却的能力</td></tr><tr><td>Special Enchantment</td><td>特殊附魔</td><td>强力，默认每件物品限一个</td></tr><tr><td>Curse Enchantment</td><td>诅咒附魔</td><td>使物品变弱</td></tr><tr><td>Artifact Enchantment</td><td>工艺品附魔</td><td>纯装饰</td></tr><tr><td>cost-exponent</td><td>成本指数</td><td>铁砧成本缩放指数</td></tr></tbody></table><h2 id="eco-核心库术语" tabindex="-1">eco 核心库术语 <a class="header-anchor" href="#eco-核心库术语" aria-label="Permalink to &quot;eco 核心库术语&quot;">​</a></h2><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>Notes</th></tr></thead><tbody><tr><td>Points</td><td>点数</td><td>按玩家/服务器/物品追踪的数值</td></tr><tr><td>Global Points</td><td>全局点数</td><td>服务器级点数</td></tr><tr><td>Item Points</td><td>物品点数</td><td>绑定到特定物品的点数</td></tr><tr><td>Item Levels</td><td>物品等级</td><td>基于 XP 的物品成长</td></tr><tr><td>Price System</td><td>价格系统</td><td>统一处理多种经济的方案</td></tr><tr><td>Math Expressions</td><td>数学表达式</td><td><code>1 + 0.2 * %level%</code> 风格的表达式</td></tr><tr><td>Custom Arguments</td><td>自定义参数</td><td>可复用的效果参数逻辑</td></tr><tr><td>Custom Placeholders</td><td>自定义占位符</td><td>在 placeholders.yml 中自定义的占位符</td></tr><tr><td>Effect Chain</td><td>效果链</td><td>一起运行的效果组</td></tr></tbody></table><h2 id="关联页面" tabindex="-1">关联页面 <a class="header-anchor" href="#关联页面" aria-label="Permalink to &quot;关联页面&quot;">​</a></h2><ul><li><a href="./guide/effect-basics">指南：Effect 基础</a></li><li><a href="./guide/ecoenchants-specific">指南：EcoEnchants 专属</a></li><li><a href="./effects/">所有效果</a></li></ul>',12)])])}const b=d(o,[["render",l]]);export{u as __pageData,b as default};
